template:
% 参数由系统自动注入：\def\a{1} \def\h{0} \def\k{0} \def\showvertex{1} \def\showaxis{1} \def\showroots{1} \def\showyint{0} \def\showpoint{0} \def\px{1.5} \def\labelp{P}
% 顶点式 y = a(x-h)^2 + k，顶点 (h,k)；disc=-k/a>=0 时有实根
\pgfmathsetmacro{\disc}{-\k/\a}
\pgfmathsetmacro{\rd}{sqrt(max(0,\disc))}
% x 视图范围：纳入原点、顶点、点 P、实根，顶点两侧保证最小展宽
\pgfmathsetmacro{\xlo}{min(0,\h,\px)-0.6}
\pgfmathsetmacro{\xhi}{max(0,\h,\px)+0.6}
\pgfmathsetmacro{\xlo}{min(\xlo,\h-2.2)}
\pgfmathsetmacro{\xhi}{max(\xhi,\h+2.2)}
\ifdim\rd pt>0.05pt
  \pgfmathsetmacro{\xlo}{min(\xlo,\h-\rd-0.6)}
  \pgfmathsetmacro{\xhi}{max(\xhi,\h+\rd+0.6)}
\fi
\pgfmathtruncatemacro{\xleft}{floor(\xlo)}
\pgfmathtruncatemacro{\xright}{ceil(\xhi)}
% 点 P 与 y 轴交点 C 的纵坐标，以及特征点上下界
\pgfmathsetmacro{\py}{\a*(\px-\h)*(\px-\h)+\k}
\pgfmathsetmacro{\yc}{\a*\h*\h+\k}
\pgfmathsetmacro{\ytopfeat}{max(0,\k,\py,\yc)}
\pgfmathsetmacro{\ybotfeat}{min(0,\k,\py,\yc)}
% y 视图以特征点为准；曲线边缘过高/过低时封顶 8 个单位（曲线在边框处截断）
\pgfmathsetmacro{\yedgeL}{\a*(\xleft-\h)*(\xleft-\h)+\k}
\pgfmathsetmacro{\yedgeR}{\a*(\xright-\h)*(\xright-\h)+\k}
\ifdim\a pt>0pt
  \pgfmathsetmacro{\yedgehi}{min(max(\yedgeL,\yedgeR),\ytopfeat+4.0)}
  \pgfmathsetmacro{\ytop}{\yedgehi+0.6}
  \pgfmathsetmacro{\ybottom}{\ybotfeat-0.6}
\else
  \pgfmathsetmacro{\yedgelo}{max(min(\yedgeL,\yedgeR),\ybotfeat-4.0)}
  \pgfmathsetmacro{\ybottom}{\yedgelo-0.6}
  \pgfmathsetmacro{\ytop}{\ytopfeat+0.6}
\fi
\pgfmathtruncatemacro{\ybottom}{floor(\ybottom)}
\pgfmathtruncatemacro{\ytop}{ceil(\ytop)}
% 曲线绘制域：截断到视图上下边之外一点，避免曲线端点撑大画布
\ifdim\a pt>0pt
  \pgfmathsetmacro{\dexit}{sqrt(max(0,(\ytop+0.3-\k)/\a))}
\else
  \pgfmathsetmacro{\dexit}{sqrt(max(0,(\ybottom-0.3-\k)/\a))}
\fi
\pgfmathsetmacro{\dlo}{max(\xleft,\h-\dexit)}
\pgfmathsetmacro{\dhi}{min(\xright,\h+\dexit)}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
% 装饰尺寸抵消 scale，保持视觉大小恒定
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$}; % ===== 对称轴 x=h（h≈0 时与 y 轴重合，跳过）=====
  \ifnum\showaxis>0
    \pgfmathsetmacro{\habsh}{abs(\h)}
    \ifdim\habsh pt>0.05pt
      \draw[dashed, gray] (\h,\ybottom) -- (\h,\ytop);
      \node[below, font=\tiny, gray] at (\h,\ytop-0.15) {$x=\h$};
    \fi
  \fi
  % ===== 抛物线 =====
  \draw[thick, domain=\dlo:\dhi, samples=120, smooth] plot (\x, {\a*(\x-\h)*(\x-\h)+\k});
  % ===== 与 x 轴交点 =====
  \ifnum\showroots>0
    \ifdim\rd pt>0.05pt
      \fill (\h-\rd,0) circle [radius=\dotr pt];
      \fill (\h+\rd,0) circle [radius=\dotr pt];
      \node[below=1pt, font=\tiny, inner sep=1pt] at (\h-\rd,0) {$x_1$};
      \node[below=1pt, font=\tiny, inner sep=1pt] at (\h+\rd,0) {$x_2$};
    \fi
  \fi
  % ===== 顶点 V =====
  \ifnum\showvertex>0
    \fill (\h,\k) circle [radius=\dotr pt];
    \ifdim\a pt>0pt
      \node[above left, font=\tiny] at (\h,\k) {$V$};
    \else
      \node[below left, font=\tiny] at (\h,\k) {$V$};
    \fi
  \fi
  % ===== 与 y 轴交点 C =====
  \ifnum\showyint>0
    \pgfmathsetmacro{\ycabs}{abs(\yc)}
    \ifdim\ycabs pt>0.05pt
      \fill (0,\yc) circle [radius=\dotr pt];
      \node[left, font=\tiny] at (0,\yc) {$C$};
    \fi
  \fi
  % ===== 曲线上点 P =====
  \ifnum\showpoint>0
    \fill (\px,\py) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
  \fi
\end{tikzpicture}
